pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }
    function testFuzz_property(uint256 timestamp) public {
        vm.assume(timestamp > 15 minutes);
        vm.warp(timestamp);
        try c.executeBatchDeposit() {} catch {}
        assertTrue(c.paused() == false);
    }
